    emit CapitalRefundedAfterCancel(amountToWithdraw, msg.sender);

    // Transfer the refunded amount back to the investor
    SafeTransferLib.safeTransfer(s_addressConfig.bidToken, msg.sender, amountToWithdraw);
}

